CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, first TEXT NOT NULL, last TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, email TEXT UNIQUE, password TEXT NOT NULL, location TEXT, city TEXT, photo TEXT, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), total NUMERIC(10,2) NOT NULL, status TEXT NOT NULL DEFAULT 'Confirmed', address TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', customer_name TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', payment_status TEXT NOT NULL DEFAULT 'demo', request_key TEXT, request_hash TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, request_key));
CREATE TABLE IF NOT EXISTS order_items (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, name TEXT NOT NULL, size TEXT NOT NULL, toppings JSONB NOT NULL, qty INTEGER NOT NULL, price NUMERIC(10,2) NOT NULL, notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id BIGINT, role TEXT NOT NULL, expires BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS orders_user_created ON orders(user_id, created_at DESC);
